# StockFlow Lab 4 - additive MVC coverage tests, test-only installation.
# Compatible with the repaired isolated Web testing harness.
$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$solution = Join-Path $root 'TradingManagementSystem.slnx'
$testsFolder = Join-Path $root 'TradingManagementSystem.Tests'
$harness = Join-Path $testsFolder 'StockFlowWebTests.cs'
$destination = Join-Path $testsFolder 'StockFlowWebAdditionalCoverageTests.cs'
$web = Join-Path $root 'TradingManagementSystem.Web\Controllers\CatalogController.cs'
$run = Join-Path $root 'measure-stockflow-web.sh'
if (!(Test-Path -LiteralPath $solution) -or !(Test-Path -LiteralPath $harness) -or
    !(Test-Path -LiteralPath $web) -or !(Test-Path -LiteralPath $run)) {
    throw 'Open Git Bash in the StockFlow solution root after installing the Web tests package.'
}
$testHost = [System.IO.File]::ReadAllText($harness)
if (!$testHost.Contains('StockFlowWebFactory') -or
    !$testHost.Contains('services.RemoveAll<TradingManagementSystem.Infrastructure.Data.MongoDbContext>();')) {
    throw 'Web tests must first use the isolated temporary MongoDB context; refusing installation.'
}
$encoded = @'

'@
$blob = [Convert]::FromBase64String($encoded.Trim())
if (Test-Path -LiteralPath $destination) {
    $existing = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($destination))
    if ($existing -ne $encoded.Trim()) {
        throw 'The additional test file already exists and differs. Nothing overwritten.'
    }
    Write-Host 'Additional Web tests already installed; no changes made.' -ForegroundColor Yellow
} else {
    $temporary = Join-Path $testsFolder ('StockFlowWebAdditionalCoverageTests.cs.tmp-' + [Guid]::NewGuid().ToString('N'))
    try {
        [System.IO.File]::WriteAllBytes($temporary, $blob)
        Move-Item -LiteralPath $temporary -Destination $destination -ErrorAction Stop
    } finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force }
    }
    Write-Host 'SUCCESS: Added additional MVC coverage tests. Production code and MongoDB unchanged.' -ForegroundColor Green
}
Write-Host 'Run in Git Bash: bash ./measure-stockflow-web.sh' -ForegroundColor Cyan
Write-Host 'Read: CoverageReport-Web/Summary.txt' -ForegroundColor Cyan
